    internal static int ItNl(byte[] b, int i) {
        // Index of the next newline at or after i, or the blob's length.
        int k = i;
        while ((k < emon.Port.BlobLen(b)) && (emon.Port.BlobU8(b, k) != 10)) {
            k += 1;
        }
        return k;
    }
    internal static int ItSemi(byte[] b, int i, int lim) {
        // Index of the next `;` in [i, lim), or lim.
        int k = i;
        while ((k < lim) && (emon.Port.BlobU8(b, k) != 59)) {
            k += 1;
        }
        return k;
    }
    internal static int ItHexval(int c) {
        if ((c >= 48) && (c <= 57)) {
            return c - 48;
        }
        if ((c >= 97) && (c <= 102)) {
            return c - 87;
        }
        return -1;
    }
    internal static int ItDec(byte[] b, int from, int to) {
        // A decimal integer, with an optional leading minus.
        int k = from;
        int v = 0;
        int neg = 0;
        if ((k < to) && (emon.Port.BlobU8(b, k) == 45)) {
            neg = 1;
            k += 1;
        }
        while (k < to) {
            v = (v * 10) + (emon.Port.BlobU8(b, k) - 48);
            k += 1;
        }
        if (neg == 1) {
            return 0 - v;
        }
        return v;
    }
    internal static int ItHexInto(byte[] b, int from, int to, emon.Port.Cells c) {
        // Decode the hex pairs in b[from, to) into c (cleared first).
        int k = from;
        emon.Port.CellsDrop(c, 0);
        while ((k + 1) < (to + 0)) {
            emon.Port.CellsPush(c, (ItHexval(emon.Port.BlobU8(b, k)) * 16) + ItHexval(emon.Port.BlobU8(b, k + 1)));
            k += 2;
        }
        return emon.Port.CellsLen(c);
    }
    internal static int ItCompare(emon.Port.Cells @out, byte[] b, int from, int to, int exact) {
        // -1 when `out` matches the hex in b[from, to): exactly, or (exact =
        // 0) as a PREFIX of it. -2 for a length problem; otherwise the
        // index of the first differing byte.
        int n = (to - from) / 2;
        int i = 0;
        if (emon.Port.CellsLen(@out) > n) {
            return -2;
        }
        if ((exact == 1) && (emon.Port.CellsLen(@out) != n)) {
            return -2;
        }
        while (i < emon.Port.CellsLen(@out)) {
            if (emon.Port.CellsAt(@out, i) != ((ItHexval(emon.Port.BlobU8(b, from + (i * 2))) * 16) + ItHexval(emon.Port.BlobU8(b, from + ((i * 2) + 1))))) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    [Xunit.Fact]
    public static void TestEveryRowOfTheZlibCorpus() {
        // Fields: name ; kind ; status ; consumed ; stream-hex ; output-hex.
        byte[] f = emon.Testport.TestFile("inflate/streams.txt");
        emon.Port.Cells src = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        int n = emon.Port.BlobLen(f);
        int pos = 0;
        int line = 0;
        int rows = 0;
        int e = 0;
        int s0 = 0;
        int s1 = 0;
        int s2 = 0;
        int s3 = 0;
        int s4 = 0;
        int kind = 0;
        int status = 0;
        int consumed = 0;
        int got = 0;
        int slen = 0;
        int exact = 0;
        while (pos < n) {
            line += 1;
            e = ItNl(f, pos);
            if ((pos < e) && (emon.Port.BlobU8(f, pos) != 35)) {
                rows += 1;
                s0 = ItSemi(f, pos, e);
                s1 = ItSemi(f, s0 + 1, e);
                s2 = ItSemi(f, s1 + 1, e);
                s3 = ItSemi(f, s2 + 1, e);
                s4 = ItSemi(f, s3 + 1, e);
                kind = emon.Port.BlobU8(f, s0 + 1);
                status = ItDec(f, s1 + 1, s2);
                consumed = ItDec(f, s2 + 1, s3);
                slen = ItHexInto(f, s3 + 1, s4, src);
                emon.Port.CellsDrop(@out, 0);
                if ((kind == 122) || (kind == 90)) {
                    got = Inflate.IzZlib(emon.Testport.CellsBlob(src), 0, slen, @out, st);
                } else {
                    got = Inflate.IzRaw(emon.Testport.CellsBlob(src), 0, slen, @out, st);
                }
                emon.Testport.AssertEqAt(got, status, "status", line);
                if (consumed >= 0) {
                    emon.Testport.AssertEqAt(Inflate.IzConsumed(st), consumed, "consumed", line);
                }
                exact = 0;
                if ((kind == 90) || (kind == 82)) {
                    exact = 1;
                }
                emon.Testport.AssertEqAt(ItCompare(@out, f, s4 + 1, e, exact), -1, "output", line);
            }
            pos = e + 1;
        }
        emon.Testport.AssertEq(rows, 346, "the corpus has this many rows");
    }
    [Xunit.Fact]
    public static void TestTheClassicStoredHello() {
        // zlib.compress(b'hello', 0): header, one stored block, Adler-32.
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Testport.AssertEq(Inflate.IzZlib(emon.Testport.HexBlob("7801 010500faff 68656c6c6f 062c0215"), 0, 16, @out, st), Inflate.IzOk(), "status");
        emon.Testport.AssertCellsHex(@out, "68656c6c6f", "hello");
        emon.Testport.AssertEq(Inflate.IzConsumed(st), 16, "consumed");
    }
